function pageSubject(s) {
  const d = SUBJ_PAGE[s.slug];
  const base = `https://${SITE.domain}`;
  const intro = d.intro.map((p) => `<p>${p}</p>`).join("");
  const why = d.why.map((p) => `<p>${p}</p>`).join("");
  const areas = d.areas.map(([t, x]) => `<h3>${t}</h3><p>${x}</p>`).join("");
  const levels = d.levels.map(([t, x]) => `<h3>${t}</h3><p>${x}</p>`).join("");
  const rec = d.rec.map((x) => `<li>${x}</li>`).join("");
  const common = d.common.map((x) => `<li>${x}</li>`).join("");
  const strategy = d.strategy.map((p) => `<p>${p}</p>`).join("");
  const faq = d.faq.map(([q, a]) => `<div class="sfaq"><b>Q. ${q}</b><p>${a}</p></div>`).join("");
  const others = SUBJECTS.filter((x) => x.slug !== s.slug)
    .map((x) => `<a href="/${x.slug}">${x.name} 화상과외</a>`).join(" · ");
  const body = `
  <div class="sub-wrap">
    <div class="crumb"><a href="/">전국화상과외</a> › ${s.name} 화상과외</div>
    <header class="sub-hero">
      <span class="sub-live">● LIVE</span>
      <h1>${s.name} 화상과외</h1>
      <p class="sub-lead">${d.lead}</p>
      <button class="sub-btn" onclick="openForm({subject:'${s.name}'})">${s.name} 화상과외 무료 상담 신청 →</button>
    </header>
    <article class="sub-body">
      <h2>${s.name} 화상과외란?</h2>${intro}
      <h2>왜 ${s.name}은 1:1 화상과외가 효과적일까요?</h2>${why}
      <h2>${s.name} 화상과외 영역별 커리큘럼</h2>${areas}
      <h2>대상별 ${s.name} 화상과외</h2>${levels}
      <h2>이런 학생에게 ${s.name} 화상과외를 추천합니다</h2>
      <p>${d.recLead}</p>
      <ul class="sub-ul">${rec}</ul>
      <h2>${s.name} 학습에서 자주 막히는 부분</h2>
      <p>${d.commonLead}</p>
      <ul class="sub-ul">${common}</ul>
      <p>${d.commonClose}</p>
      <h2>${s.name} 성적을 올리는 학습 전략</h2>${strategy}
      <h2>스터디온라이브 ${s.name} 화상과외 진행 방식</h2>
      <p>모든 수업은 검증된 선생님과 1:1 실시간 화상으로 진행됩니다. 학생은 학원에 오갈 필요 없이 집에서 편하게 수업을 받고, 부모님은 안전하게 아이의 학습을 맡길 수 있습니다. 수업 자료와 필기는 화면으로 공유되어 복습이 편리하며, 첫 수업 전 무료 상담으로 학생 수준을 진단한 뒤 ${s.name} 학습 목표에 맞는 선생님과 커리큘럼을 매칭해 드립니다.</p>
      <ul class="sub-ul">
        <li>전국 어디서나 동일한 품질의 1:1 ${s.name} 수업</li>
        <li>학생 수준 진단 후 맞춤 커리큘럼 설계</li>
        <li>내신·수능·기초 보완 등 목표별 수업</li>
        <li>수업 자료·필기 공유로 편리한 복습</li>
      </ul>
      <h2>자주 묻는 질문</h2>${faq}
      <div class="sub-cta">
        <h2>${s.name} 화상과외, 지금 무료로 상담받으세요</h2>
        <p>전국 어디서나 검증된 ${s.name} 선생님과 1:1로 시작할 수 있습니다. 상담은 무료이며 부담 없이 신청하실 수 있습니다.</p>
        <button class="sub-btn" onclick="openForm({subject:'${s.name}'})">무료 상담 신청 →</button>
      </div>
      <p class="sub-others">다른 과목 화상과외: ${others}</p>
    </article>
  </div>`;
  return layout({
    title: `${s.name} 화상과외 | 1:1 온라인 ${s.name} 과외 - ${SITE.name}`,
    desc: d.desc,
    canonical: `${base}/${s.slug}`,
    body,
  });
}

function pageAllRegions() {
  const map = {};
  const order = [];
  for (const r of regions) {
    const parts = r.name.split(" ");
    const sido = r.sido || parts[0];
    const dong = r.dong || parts[parts.length - 1];
    const gu = parts.slice(1, -1).join(" ") || sido;
    if (!map[sido]) {
      map[sido] = {};
      order.push(sido);
    }
    (map[sido][gu] = map[sido][gu] || []).push([dong, r.slug]);
  }
  const SIDO_ORDER = ["서울특별시", "부산광역시", "대구광역시", "인천광역시", "광주광역시", "대전광역시", "울산광역시", "세종특별자치시", "경기도", "강원특별자치도", "충청북도", "충청남도", "전북특별자치도", "전라남도", "경상북도", "경상남도", "제주특별자치도"];
  order.sort((a, b) => (SIDO_ORDER.indexOf(a) < 0 ? 99 : SIDO_ORDER.indexOf(a)) - (SIDO_ORDER.indexOf(b) < 0 ? 99 : SIDO_ORDER.indexOf(b)));
  let sections = "";
  for (const sido of order) {
    const gus = map[sido];
    let total = 0;
    let guHtml = "";
    for (const gu of Object.keys(gus)) {
      const list = gus[gu];
      total += list.length;
      guHtml +=
        `<div class="reg-gu"><h3>${gu}</h3><div class="reg-dongs">` +
        list.map(([d, sl]) => `<a href="/${sl}">${d}</a>`).join("") +
        `</div></div>`;
    }
    sections += `<details class="reg-sido"><summary><b>${sido}</b><span>${total}개 지역</span></summary><div class="reg-body">${guHtml}</div></details>`;
  }
  const body = `
  <div class="reg-wrap">
    <div class="crumb"><a href="/">홈</a> › 전국 화상과외</div>
    <header class="reg-hero">
      <h1>전국 화상과외 지역</h1>
      <p>전국 모든 시·군·구·읍·면·동의 1:1 화상과외 매칭 페이지입니다. 우리 동네를 찾아 검증된 선생님과 바로 상담을 신청하세요.</p>
    </header>
    ${sections}
  </div>`;
  return layout({
    title: `전국 화상과외 지역 목록 | ${SITE.name}`,
    desc: "전국 모든 시·군·구·읍·면·동 1:1 화상과외 매칭. 우리 동네 화상과외 선생님을 찾아보세요.",
    canonical: `https://${SITE.domain}/regions`,
    body,
  });
}

