function sitemap() {
  const urls = [`https://${SITE.domain}/`, `https://${SITE.domain}/regions`];
  for (const s of SUBJECTS) {
    urls.push(`https://${SITE.domain}/${s.slug}`);
  }
  for (const r of regions) {
    urls.push(`https://${SITE.domain}/${r.slug}`);
    for (const s of SUBJECTS) {
      urls.push(`https://${SITE.domain}/${r.slug}/${s.slug}`);
    }
  }
  const body =
    `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n` +
    urls.map((u) => `  <url><loc>${u}</loc></url>`).join("\n") +
    `\n</urlset>`;
  return new Response(body, { headers: { "content-type": "application/xml" } });
}

function rss() {
  const base = `https://${SITE.domain}`;
  const now = new Date().toUTCString();
  const xe = (t) => String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  let items = "", count = 0;
  for (const r of regions) {
    for (const s of SUBJECTS) {
      const u = `${base}/${r.slug}/${s.slug}`;
      items +=
        `  <item><title>${xe(r.name + " " + s.name + " 1:1 화상과외")}</title>` +
        `<link>${u}</link><guid>${u}</guid>` +
        `<description>${xe(r.name + " " + s.name + " 온라인 1:1 화상과외 매칭. 집에서 검증된 선생님과 실시간 수업, 무료 상담.")}</description>` +
        `<pubDate>${now}</pubDate></item>\n`;
      if (++count >= 1000) break;
    }
    if (count >= 1000) break;
  }
  const body =
    `<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0">\n<channel>\n` +
    `<title>${xe(SITE.name)}</title>\n<link>${base}</link>\n` +
    `<description>${xe(SITE.desc)}</description>\n<language>ko</language>\n` +
    `<lastBuildDate>${now}</lastBuildDate>\n` +
    items +
    `</channel>\n</rss>`;
  return new Response(body, { headers: { "content-type": "application/rss+xml; charset=UTF-8" } });
}

// ─────────────────────────────────────────────────────────────
// HTML 래퍼
// ─────────────────────────────────────────────────────────────
function html(body, status = 200) {
  return new Response(body, {
    status,
    headers: { "content-type": "text/html;charset=UTF-8" },
  });
}

function layout({ title, desc, canonical, body, image }) {
  const ogImage = image || CDN+"main/aa.jpg";
  return `<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="naver-site-verification" content="cc44e4b11087ddf273b1aa4f00c27b4da881754d" />
<meta name="DaumWebMasterTool" content="b60bbf918a59e93331f9ec53dc2a39ea938384c1e4e51dd5dccf10ac7a040dc1:MeMBEDgiMukoYtb9XFlQLw==" />
<link rel="icon" type="image/svg+xml" href="/favicon.svg">
<link rel="apple-touch-icon" href="/favicon.svg">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${title}</title>
<meta name="description" content="${desc}">
<link rel="canonical" href="${canonical}">
<meta property="og:title" content="${title}">
<meta property="og:description" content="${desc}">
<meta property="og:type" content="website">
<meta property="og:url" content="${canonical}">
<meta property="og:site_name" content="${SITE.name}">
<meta property="og:image" content="${ogImage}">
<meta name="robots" content="index,follow">
<style>${CSS}</style>
</head>
<body>
${HEADER}
${body}
${FOOTER}
${FORM_MODAL}
<script>${JS}</script>
</body>
</html>`;
}

// ─────────────────────────────────────────────────────────────
// 디자인 (CSS) — 밝고 깔끔 + 디지털 느낌
// ─────────────────────────────────────────────────────────────
const CSS = `
:root{
  --bg:#fbfcff; --surface:#ffffff; --ink:#0b1020; --muted:#5b6478;
  --line:#e7ebf3; --brand:#2f6bff; --brand2:#6a4bff; --accent:#00d4c8;
  --glow:rgba(47,107,255,.14);
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;overflow-x:hidden}
body{
  font-family:'Pretendard','Apple SD Gothic Neo',-apple-system,BlinkMacSystemFont,system-ui,sans-serif;
  background:var(--bg);color:var(--ink);line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden;word-break:keep-all;
}
img{max-width:100%}
a{color:inherit;text-decoration:none}
.wrap{max-width:1160px;margin:0 auto;padding:0 24px}

/* 헤더 */
header.nav{position:sticky;top:0;z-index:50;backdrop-filter:blur(14px);
  background:rgba(251,252,255,.82);border-bottom:1px solid var(--line)}
.nav-in{display:flex;align-items:center;justify-content:space-between;height:128px}
.logo{display:flex;align-items:center;gap:0;font-weight:800;font-size:19px;letter-spacing:-.02em;white-space:nowrap}
.logo .live-mark{display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:900;
  color:#fff;background:#e63946;padding:4px 9px;border-radius:999px;letter-spacing:.05em;margin-right:9px}
.logo .live-mark::before{content:"";width:7px;height:7px;border-radius:50%;background:#fff;
  box-shadow:0 0 0 0 rgba(255,255,255,.6);animation:livepulse 1.6s infinite}
@keyframes livepulse{0%{box-shadow:0 0 0 0 rgba(255,255,255,.7)}100%{box-shadow:0 0 0 6px transparent}}
.logo b{color:var(--brand)}
.logo .on{color:#b00710;font-weight:900}
.nav-cta{font-size:14px;font-weight:700;padding:9px 18px;border-radius:999px;
  background:var(--ink);color:#fff;transition:.2s}
.nav-cta:hover{transform:translateY(-1px)}
@media(max-width:600px){
  .nav-in{height:64px}
  .logo{font-size:15px;gap:0}
  .logo .live-mark{font-size:9px;padding:3px 6px;gap:4px;margin-right:7px}
  .nav-cta{font-size:12.5px;padding:8px 13px}
}

/* 히어로 */
.hero{position:relative;overflow:hidden;padding:88px 0 64px}
.hero::before{content:"";position:absolute;inset:0;z-index:0;
  background:
    radial-gradient(60% 50% at 75% 0%,rgba(106,75,255,.10),transparent 70%),
    radial-gradient(50% 50% at 10% 20%,rgba(0,212,200,.10),transparent 70%);
}
.grid-bg{position:absolute;inset:0;z-index:0;opacity:.5;
  background-image:linear-gradient(var(--line) 1px,transparent 1px),
    linear-gradient(90deg,var(--line) 1px,transparent 1px);
  background-size:44px 44px;mask-image:linear-gradient(180deg,#000,transparent 80%)}
.hero-in{position:relative;z-index:1;text-align:center}
.badge{display:inline-flex;align-items:center;gap:8px;font-size:13px;font-weight:700;
  color:var(--brand);background:#fff;border:1px solid var(--line);padding:7px 15px;
  border-radius:999px;box-shadow:0 2px 10px rgba(20,40,90,.05);margin-bottom:24px}
.badge .live{width:7px;height:7px;border-radius:50%;background:var(--accent);
  box-shadow:0 0 0 0 var(--accent);animation:live 1.6s infinite}
@keyframes live{0%{box-shadow:0 0 0 0 rgba(0,212,200,.6)}100%{box-shadow:0 0 0 8px transparent}}
.hero h1{font-size:clamp(34px,6vw,60px);font-weight:900;letter-spacing:-.035em;line-height:1.08}
.hero h1 .g{background:linear-gradient(100deg,var(--brand),var(--brand2));
  -webkit-background-clip:text;background-clip:text;color:transparent}
.hero p.sub{margin:22px auto 0;max-width:560px;font-size:17px;color:var(--muted)}
.hero-cta{margin-top:34px;display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.btn{font-size:15px;font-weight:700;padding:14px 26px;border-radius:14px;cursor:pointer;
  border:none;transition:.2s;display:inline-flex;align-items:center;gap:8px}
.btn-p{background:linear-gradient(100deg,var(--brand),var(--brand2));color:#fff;
  box-shadow:0 10px 26px -8px var(--brand)}
.btn-p:hover{transform:translateY(-2px);box-shadow:0 16px 34px -8px var(--brand)}
.btn-o{background:#fff;border:1px solid var(--line);color:var(--ink)}
.btn-o:hover{border-color:var(--brand);color:var(--brand)}

/* 통계 */
.stats{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:48px}
.stat{background:var(--surface);border:1px solid var(--line);border-radius:18px;
  padding:20px 26px;min-width:150px;box-shadow:0 4px 18px rgba(20,40,90,.04)}
.stat .n{font-size:28px;font-weight:900;letter-spacing:-.03em;
  background:linear-gradient(100deg,var(--brand),var(--brand2));
  -webkit-background-clip:text;background-clip:text;color:transparent}
.stat .l{font-size:13px;color:var(--muted);font-weight:600;margin-top:2px}

/* 섹션 */
section{padding:64px 0}
.sec-head{text-align:center;margin-bottom:40px}
.sec-head .k{font-size:13px;font-weight:800;color:var(--brand);letter-spacing:.08em;text-transform:uppercase}
.sec-head h2{font-size:clamp(26px,4vw,38px);font-weight:900;letter-spacing:-.03em;margin-top:8px}
.sec-head p{color:var(--muted);margin-top:10px;font-size:16px}

/* 과목 카드 */
.subj-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}
@media(max-width:760px){.subj-grid{grid-template-columns:repeat(2,1fr)}}

/* 라이트 인터랙티브 과목 (대형1+리스트4) */
.lsubj{display:grid;grid-template-columns:1.1fr 1fr;gap:18px}
@media(max-width:780px){.lsubj{grid-template-columns:1fr}}
.lfeat{background:linear-gradient(135deg,#0b1020,#2a2f4d);color:#fff;border-radius:24px;padding:36px;
  display:flex;flex-direction:column;justify-content:space-between;min-height:340px;cursor:pointer;
  transition:.2s;position:relative;overflow:hidden}
.lfeat:hover{transform:translateY(-4px);box-shadow:0 24px 50px -20px rgba(11,16,32,.4)}
.lfeat .bg-text{position:absolute;right:-40px;bottom:-70px;font-size:280px;font-weight:900;color:rgba(255,255,255,.04);line-height:1;transition:.4s}
.lfeat>*{position:relative;z-index:1}
.lfeat .top{display:flex;align-items:center;gap:10px}
.lfeat .live{font-size:11px;font-weight:900;color:#fff;background:#e63946;padding:4px 10px;border-radius:5px;letter-spacing:.05em;display:inline-flex;align-items:center;gap:5px}
.lfeat .live::before{content:"";width:6px;height:6px;border-radius:50%;background:#fff;animation:livepulse 1.4s infinite}
.lfeat .tag{font-size:12px;font-weight:800;color:#7be3d3;letter-spacing:.1em}
.lfeat h3{font-size:54px;font-weight:900;letter-spacing:-.04em;margin-top:18px;line-height:1;transition:.3s}
.lfeat .sub{font-size:15px;opacity:.85;margin-top:12px;max-width:340px;line-height:1.6}
.lfeat .meta{display:flex;gap:18px;margin-top:22px;flex-wrap:wrap}
.lfeat .meta div{font-size:13px;opacity:.8}
.lfeat .meta b{font-size:16px;font-weight:900;color:#fff;display:block}
.lfeat .go{font-size:14px;font-weight:800;display:inline-flex;align-items:center;gap:8px;background:#fff;color:var(--ink);
  padding:12px 20px;border-radius:10px;width:fit-content;margin-top:22px;cursor:pointer}
.lfade{animation:lfadeanim .35s ease}
@keyframes lfadeanim{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.llist{background:#fff;border:1px solid var(--line);border-radius:24px;padding:14px 24px;display:flex;flex-direction:column;justify-content:center}
.litem{display:flex;align-items:center;gap:18px;padding:20px 0;border-bottom:1px dashed var(--line);cursor:pointer;transition:.18s}
.litem:last-child{border-bottom:0}
.litem .dot{width:10px;height:10px;border-radius:50%;background:var(--line);transition:.3s;flex:0 0 10px}
.litem:hover,.litem.act{padding-left:8px}
.litem:hover .dot,.litem.act .dot{background:var(--brand);box-shadow:0 0 0 6px rgba(47,107,255,.15);transform:scale(1.3)}
.litem:hover .nm,.litem.act .nm{color:var(--brand)}
.litem .nm{font-size:22px;font-weight:800;letter-spacing:-.02em;flex:1;transition:.2s}
.litem .nm small{font-size:13px;font-weight:600;color:var(--muted);margin-left:10px}
.litem .live{font-size:10px;font-weight:900;color:#fff;background:#e63946;padding:3px 8px;border-radius:5px}
.litem .arr{font-size:18px;color:var(--ink);opacity:.3;transition:.2s}
.litem:hover .arr,.litem.act .arr{opacity:1;transform:translateX(4px)}
.subj{background:var(--surface);border:1px solid var(--line);border-radius:18px;
  padding:26px 18px;text-align:center;transition:.22s;cursor:pointer}
.subj:hover{transform:translateY(-4px);border-color:var(--brand);
  box-shadow:0 18px 40px -16px var(--glow)}
.subj .ic{font-size:34px}
.subj .nm{font-weight:800;margin-top:10px;font-size:17px}
.subj .dc{font-size:13px;color:var(--muted);margin-top:3px;word-break:keep-all}

/* 지역 칩 */
.region-tabs{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-bottom:26px}
.rt{font-size:14px;font-weight:700;padding:9px 16px;border-radius:999px;
  background:#fff;border:1px solid var(--line);cursor:pointer;transition:.18s}
.rt:hover,.rt.on{background:var(--brand);color:#fff;border-color:var(--brand)}
.region-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px}
.region-list a{font-size:14px;padding:11px 14px;border-radius:12px;background:#fff;
  border:1px solid var(--line);color:var(--muted);font-weight:600;transition:.16s;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.region-list a:hover{color:var(--brand);border-color:var(--brand);background:#f5f8ff}

/* 피처 */
.feat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
@media(max-width:860px){.feat-grid{grid-template-columns:1fr}}
.feat{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:30px}
.feat .ic{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;
  font-size:22px;background:linear-gradient(135deg,#eef3ff,#f2effe);margin-bottom:8px}
.feat h3{font-size:19px;font-weight:800;letter-spacing:-.02em}
.feat p{color:var(--muted);font-size:15px;margin-top:8px}

/* 지역 페이지 히어로 */
.rhero{padding:64px 0 36px;position:relative;overflow:hidden}
.rhero::before{content:"";position:absolute;inset:0;
  background:radial-gradient(50% 60% at 80% 0%,rgba(47,107,255,.08),transparent 70%)}
.rhero-in{position:relative;z-index:1}
.crumb{font-size:13px;color:var(--muted);font-weight:600;margin-bottom:14px}
.crumb a:hover{color:var(--brand)}
.rhero h1{font-size:clamp(28px,5vw,44px);font-weight:900;letter-spacing:-.03em;line-height:1.12}
.rhero h1 .g{background:linear-gradient(100deg,var(--brand),var(--brand2));
  -webkit-background-clip:text;background-clip:text;color:transparent}
.rhero p{color:var(--muted);font-size:16px;margin-top:14px;max-width:620px}

/* 콘텐츠 박스 */
.cbox{background:var(--surface);border:1px solid var(--line);border-radius:20px;
  padding:30px;margin-top:18px}
.cbox h2{font-size:21px;font-weight:800;letter-spacing:-.02em;margin-bottom:10px}
.cbox h2:not(:first-child){margin-top:24px}
.cbox p{color:var(--muted);font-size:15.5px;margin-top:8px}
.cbox ul{margin:12px 0 0 2px;list-style:none}
.cbox li{padding-left:26px;position:relative;color:var(--muted);font-size:15.5px;margin-top:9px}
.cbox li::before{content:"";position:absolute;left:0;top:9px;width:14px;height:14px;
  border-radius:5px;background:linear-gradient(135deg,var(--brand),var(--brand2))}

/* 푸터 */
footer{border-top:1px solid var(--line);padding:48px 0 60px;margin-top:40px;background:#fff}
.foot-top{display:flex;justify-content:space-between;gap:30px;flex-wrap:wrap}
.foot-top .logo{font-size:17px}
.foot-links{display:flex;gap:22px;flex-wrap:wrap;font-size:14px;color:var(--muted);font-weight:600}
.foot-links a:hover{color:var(--brand)}
.foot-bot{margin-top:28px;padding-top:22px;border-top:1px solid var(--line);
  font-size:13px;color:var(--muted);display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}
.notice{font-size:12.5px;color:#9aa3b5;margin-top:14px}
.field label.req::after{content:" *";color:#e63946;font-weight:700}
.addr-row{display:flex;gap:8px}
.addr-row input{flex:1}
.addr-row input[readonly]{cursor:pointer;background:#f7f8fc}
.addr-srch{flex:none;padding:0 16px;border-radius:10px;border:1px solid var(--line);background:var(--ink);color:#fff;font-weight:700;font-size:13px;cursor:pointer;white-space:nowrap}
.addr-srch:hover{opacity:.9}
/* 과목 상세페이지 */
.go{text-decoration:none}
.sub-wrap{max-width:800px;margin:0 auto;padding:30px 22px 80px}
.sub-hero{position:relative;padding:40px 34px;margin-bottom:40px;border-radius:22px;background:linear-gradient(160deg,#f4f7ff 0%,#f6f2ff 100%);border:1px solid var(--line);overflow:hidden}
.sub-hero::before{content:"";position:absolute;top:-60px;right:-40px;width:220px;height:220px;border-radius:50%;background:radial-gradient(circle,rgba(106,75,255,.16),transparent 70%)}
.sub-live{position:relative;display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:800;color:#e11d48;letter-spacing:.6px;background:rgba(225,29,72,.1);padding:5px 12px;border-radius:999px;margin-bottom:16px}
.sub-hero h1{position:relative;font-size:40px;font-weight:800;line-height:1.18;letter-spacing:-.5px;margin-bottom:14px;color:var(--ink)}
.sub-lead{position:relative;font-size:18px;color:var(--muted);line-height:1.65;margin-bottom:26px;max-width:560px}
.sub-btn{position:relative;display:inline-block;padding:15px 28px;border:none;border-radius:13px;background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;font-size:15px;font-weight:700;cursor:pointer;box-shadow:0 8px 22px rgba(47,107,255,.28);transition:.2s}
.sub-btn:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(47,107,255,.36)}
.sub-body h2{font-size:24px;font-weight:800;margin:42px 0 16px;line-height:1.35;color:var(--ink);padding-left:14px;border-left:4px solid var(--brand)}
.sub-body h3{font-size:17.5px;font-weight:700;margin:22px 0 8px;color:var(--ink);padding-left:12px;border-left:3px solid var(--accent)}
.sub-body p{font-size:16px;line-height:1.9;color:#3a4256;margin-bottom:16px}
.sub-ul{margin:10px 0 18px;padding:0;list-style:none}
.sub-ul li{position:relative;font-size:16px;line-height:1.8;color:#3a4256;padding-left:26px;margin-bottom:8px}
.sub-ul li::before{content:"";position:absolute;left:6px;top:11px;width:7px;height:7px;border-radius:50%;background:var(--brand)}
.sfaq{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin-bottom:12px;box-shadow:0 1px 3px rgba(11,16,32,.04)}
.sfaq b{display:block;font-size:16px;font-weight:700;margin-bottom:7px;color:var(--brand)}
.sfaq p{margin:0;font-size:15.5px;line-height:1.75;color:#4a5266}
.sub-cta{background:linear-gradient(135deg,#eef3ff,#f1ecff);border:1px solid rgba(106,75,255,.16);border-radius:20px;padding:36px 28px;margin:46px 0 26px;text-align:center}
.sub-cta h2{border:none;padding:0;margin:0 0 10px;font-size:23px}
.sub-cta p{margin:0 auto 20px;max-width:520px;color:var(--muted)}
.sub-others{font-size:14.5px;color:var(--muted);margin-top:28px;padding-top:22px;border-top:1px solid var(--line)}
.sub-others a{color:var(--brand2);font-weight:600;text-decoration:none}
.sub-others a:hover{text-decoration:underline}
@media(max-width:600px){.sub-wrap{padding:20px 16px 60px}.sub-hero{padding:30px 22px;border-radius:18px}.sub-hero h1{font-size:30px}.sub-lead{font-size:16.5px}.sub-body h2{font-size:21px;margin:34px 0 14px}.sub-body p,.sub-ul li{font-size:15.5px}}
/* 전국 지역 디렉토리 */
.reg-wrap{max-width:920px;margin:0 auto;padding:30px 22px 80px}
.reg-hero{margin-bottom:24px}
.reg-hero h1{font-size:34px;font-weight:800;margin-bottom:10px;color:var(--ink)}
.reg-hero p{font-size:16px;color:var(--muted);line-height:1.7;max-width:620px}
.reg-sido{border:1px solid var(--line);border-radius:14px;margin-bottom:12px;background:var(--surface);overflow:hidden}
.reg-sido summary{display:flex;align-items:center;gap:12px;padding:18px 22px;cursor:pointer;font-size:18px;list-style:none}
.reg-sido summary::-webkit-details-marker{display:none}
.reg-sido summary b{flex:1;font-weight:800;color:var(--ink)}
.reg-sido summary span{font-size:13px;font-weight:600;color:var(--muted);background:var(--bg);padding:4px 12px;border-radius:999px}
.reg-sido summary::after{content:"▾";color:var(--muted);transition:.2s;font-size:14px}
.reg-sido[open] summary::after{transform:rotate(180deg)}
.reg-body{padding:4px 22px 20px;border-top:1px solid var(--line)}
.reg-gu{padding:14px 0;border-bottom:1px dashed var(--line)}
.reg-gu:last-child{border-bottom:none}
.reg-gu h3{font-size:15px;font-weight:700;color:var(--brand);margin-bottom:10px}
.reg-dongs{display:flex;flex-wrap:wrap;gap:8px 14px}
.reg-dongs a{font-size:14px;color:#3a4256;text-decoration:none}
.reg-dongs a:hover{color:var(--brand);text-decoration:underline}
@media(max-width:600px){.reg-wrap{padding:20px 16px 60px}.reg-hero h1{font-size:27px}.reg-sido summary{padding:15px 18px;font-size:16px}.reg-body{padding:4px 16px 16px}.reg-dongs{gap:7px 12px}.reg-dongs a{font-size:13.5px}}

/* 플로팅 CTA */
.fab{position:fixed;right:22px;bottom:22px;z-index:60;
  background:linear-gradient(100deg,var(--brand),var(--brand2));color:#fff;
  font-weight:800;font-size:15px;padding:15px 24px;border-radius:999px;border:none;cursor:pointer;
  box-shadow:0 14px 34px -10px var(--brand);transition:.2s;display:flex;align-items:center;gap:8px}
.fab:hover{transform:translateY(-2px) scale(1.02)}

/* 모달 */
.modal{position:fixed;inset:0;z-index:100;display:none;align-items:center;justify-content:center;
  background:rgba(11,16,32,.5);backdrop-filter:blur(4px);padding:20px}
.modal.open{display:flex}
.modal-card{background:#fff;border-radius:24px;max-width:460px;width:100%;padding:30px;
  box-shadow:0 30px 80px -20px rgba(11,16,32,.5);max-height:92vh;overflow:auto;animation:pop .25s ease}
@keyframes pop{from{transform:translateY(14px) scale(.98);opacity:0}to{transform:none;opacity:1}}
.modal-card h3{font-size:22px;font-weight:900;letter-spacing:-.02em}
.modal-card .ms{color:var(--muted);font-size:14px;margin-top:6px;margin-bottom:20px}
.field{margin-bottom:14px}
.field label{display:block;font-size:13px;font-weight:700;margin-bottom:6px}
.field input,.field select,.field textarea{width:100%;padding:12px 14px;border:1px solid var(--line);
  border-radius:12px;font-size:15px;font-family:inherit;background:#fbfcff;transition:.16s}
.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--brand);
  background:#fff;box-shadow:0 0 0 3px var(--glow)}
.field textarea{resize:vertical;min-height:80px}
.modal-x{position:absolute;top:18px;right:18px;font-size:22px;color:var(--muted);
  cursor:pointer;background:none;border:none;line-height:1}
.modal-card{position:relative}
.msg-ok{text-align:center;padding:20px 0}
.msg-ok .big{font-size:46px}
.msg-ok h3{margin-top:10px}

/* 썸네일 (지역+화상과외 오버레이) */
.thumb{position:relative;width:100%;aspect-ratio:1200/520;border-radius:20px;overflow:hidden;
  margin-top:8px;background:#dfe6f3}
.thumb img{width:100%;height:100%;object-fit:cover;display:block}
.thumb .ov{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;
  padding:30px;background:linear-gradient(180deg,rgba(11,16,32,.05),rgba(11,16,32,.72))}
.thumb .ov .kw{display:inline-block;align-self:flex-start;font-size:13px;font-weight:800;
  color:#fff;background:rgba(47,107,255,.9);padding:6px 13px;border-radius:999px;margin-bottom:12px}
.thumb .ov h2{color:#fff;font-size:clamp(24px,4.5vw,38px);font-weight:900;letter-spacing:-.03em;
  line-height:1.15;text-shadow:0 2px 14px rgba(0,0,0,.3)}
@media(max-width:600px){
  .thumb{aspect-ratio:4/3;margin-top:14px}
  .thumb .ov{padding:22px;justify-content:flex-end}
  .thumb .ov .kw{margin-bottom:10px}
  .thumb .ov h2{font-size:28px}
}

/* 본문 아티클 */
.article{background:var(--surface);border:1px solid var(--line);border-radius:20px;
  padding:34px;margin-top:20px}
.article h2{font-size:21px;font-weight:800;letter-spacing:-.02em;margin:26px 0 10px;
  padding-top:8px}
.article h2:first-child{margin-top:0}
.article p{color:#384256;font-size:15.5px;line-height:1.85;margin-top:10px}
.article blockquote{margin:12px 0;padding:14px 18px;background:#f5f8ff;border-left:3px solid var(--brand);
  border-radius:0 12px 12px 0;color:#4a5468;font-size:15px;font-style:italic}
.article .trial{margin-top:24px;padding:22px 24px;border-radius:16px;
  background:linear-gradient(120deg,#eef3ff,#f3effe);border:1px solid #e0e6fb;
  display:flex;flex-direction:column;gap:6px}
.article .trial strong{font-size:17px;font-weight:800;color:var(--brand2)}
.article .trial span{font-size:14.5px;color:#4a5468}

/* 날짜 메타 */
.datemeta{display:flex;gap:16px;flex-wrap:wrap;font-size:13px;color:var(--muted);
  margin-top:14px;font-weight:600}
.datemeta span b{color:#384256;font-weight:700}

/* ── 본문 시각 컴포넌트 ── */
/* 포인트 카드 3열 */
.pcards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}
@media(max-width:680px){.pcards{grid-template-columns:1fr}}
.pcard{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px 18px;text-align:center;
  transition:.2s}
.pcard:hover{transform:translateY(-3px);box-shadow:0 14px 30px -16px var(--glow);border-color:var(--brand)}
.pcard .ic{width:52px;height:52px;border-radius:15px;display:grid;place-items:center;font-size:26px;
  margin:0 auto 12px;background:linear-gradient(135deg,#eef3ff,#f2effe)}
.pcard b{display:block;font-size:16px;font-weight:800;letter-spacing:-.02em}
.pcard span{display:block;font-size:13.5px;color:var(--muted);margin-top:5px;line-height:1.5}

/* 숫자 통계 박스 */
.numbox{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}
@media(max-width:680px){.numbox{grid-template-columns:repeat(2,1fr)}}
.numbox .nb{border-radius:16px;padding:20px 14px;text-align:center;color:#fff;
  background:linear-gradient(135deg,var(--brand),var(--brand2))}
.numbox .nb:nth-child(2){background:linear-gradient(135deg,#00b8d4,#00d4c8)}
.numbox .nb:nth-child(3){background:linear-gradient(135deg,#7c4dff,#b388ff)}
.numbox .nb:nth-child(4){background:linear-gradient(135deg,#ff7043,#ff9776)}
.numbox .nb .n{font-size:24px;font-weight:900;letter-spacing:-.02em}
.numbox .nb .l{font-size:12.5px;opacity:.92;margin-top:3px;font-weight:600}

/* 단계 (1·2·3) */
.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}
@media(max-width:680px){.steps{grid-template-columns:1fr}}
.step{position:relative;background:#fbfcff;border:1px solid var(--line);border-radius:16px;padding:24px 18px 20px}
.step .no{position:absolute;top:-12px;left:18px;width:32px;height:32px;border-radius:50%;
  background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;font-weight:900;
  display:grid;place-items:center;font-size:15px;box-shadow:0 6px 14px -4px var(--brand)}
.step b{display:block;font-size:16px;font-weight:800;margin-top:8px}
.step span{display:block;font-size:14px;color:var(--muted);margin-top:6px;line-height:1.6}

/* 체크리스트 박스 */
.checkbox-list{background:linear-gradient(120deg,#f5f8ff,#f3effe);border:1px solid #e4eafd;
  border-radius:18px;padding:24px 26px;margin:22px 0}
.checkbox-list h3{font-size:17px;font-weight:800;margin-bottom:14px;display:flex;align-items:center;gap:8px}
.checkbox-list .ci{display:flex;align-items:flex-start;gap:11px;margin-top:11px;font-size:15px;color:#384256}
.checkbox-list .ci .ck{flex:0 0 22px;width:22px;height:22px;border-radius:7px;
  background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;display:grid;place-items:center;
  font-size:13px;font-weight:900;margin-top:1px}

/* 강조 인용 (포인트) */
.highlight{margin:22px 0;padding:22px 24px;border-radius:16px;background:#fff;
  border:1px solid var(--line);border-left:5px solid var(--brand);
  font-size:16px;color:#2b3344;line-height:1.7;font-weight:600}
.highlight .em{color:var(--brand);font-weight:800}

/* 과목 배지 행 */
.subj-badges{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}
.subj-badges .sb{font-size:13.5px;font-weight:700;padding:8px 15px;border-radius:999px;
  background:#fff;border:1px solid var(--line);display:flex;align-items:center;gap:6px}

/* 구분선 (그라데이션) */
.divider{height:2px;border:0;margin:30px 0;
  background:linear-gradient(90deg,transparent,var(--line) 20%,var(--line) 80%,transparent)}

/* FAQ 아코디언 느낌 박스 */
.qa{border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin-top:12px;background:#fff}
.qa .q{font-weight:800;font-size:15.5px;display:flex;gap:8px;align-items:flex-start}
.qa .q .qi{color:var(--brand);font-weight:900}
.qa .a{font-size:14.5px;color:var(--muted);margin-top:8px;line-height:1.7;padding-left:24px}

/* 비교 표 */
.compare{width:100%;border-collapse:separate;border-spacing:0;margin:22px 0;font-size:14.5px;
  border:1px solid var(--line);border-radius:16px;overflow:hidden}
.compare th,.compare td{padding:14px 16px;text-align:left;border-bottom:1px solid var(--line)}
.compare thead th{background:#f7f9fd;font-weight:800;font-size:14px}
.compare thead th:last-child{color:var(--brand)}
.compare tbody tr:last-child td{border-bottom:0}
.compare td:first-child{font-weight:700;color:#384256;background:#fbfcff}
.compare .x{color:#b4254a;font-weight:700}
.compare .o{color:var(--brand);font-weight:800}

/* 진행률 바 */
.progress-block{margin:22px 0;background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px 24px}
.progress-block h3{font-size:16px;font-weight:800;margin-bottom:16px}
.pbar{margin-top:14px}
.pbar .lab{display:flex;justify-content:space-between;font-size:13.5px;font-weight:700;margin-bottom:6px}
.pbar .track{height:10px;background:#eef1f7;border-radius:99px;overflow:hidden}
.pbar .fill{height:100%;border-radius:99px;background:linear-gradient(90deg,var(--brand),var(--brand2))}
.pbar .fill.c2{background:linear-gradient(90deg,#00b8d4,#00d4c8)}
.pbar .fill.c3{background:linear-gradient(90deg,#7c4dff,#b388ff)}

/* 별점 평점 */
.rating-box{display:flex;align-items:center;gap:22px;flex-wrap:wrap;margin:22px 0;
  background:linear-gradient(120deg,#f7f9fd,#f3effe);border:1px solid #e4eafd;
  border-radius:18px;padding:24px 28px}
.rating-box .score{font-size:46px;font-weight:900;letter-spacing:-.03em;line-height:1;
  background:linear-gradient(135deg,var(--brand),var(--brand2));-webkit-background-clip:text;
  background-clip:text;color:transparent}
.rating-box .stars{font-size:20px;letter-spacing:2px}
.rating-box .meta{font-size:13.5px;color:var(--muted);margin-top:4px;font-weight:600}

/* 말풍선 후기 */
.testi{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:22px 0}
@media(max-width:680px){.testi{grid-template-columns:1fr}}
.tcard{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px}
.tcard .top{display:flex;align-items:center;gap:11px;margin-bottom:11px}
.tcard .av{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;
  font-size:18px;font-weight:800;color:#fff;background:linear-gradient(135deg,var(--brand),var(--brand2))}
.tcard .av.a2{background:linear-gradient(135deg,#00b8d4,#00d4c8)}
.tcard .av.a3{background:linear-gradient(135deg,#7c4dff,#b388ff)}
.tcard .av.a4{background:linear-gradient(135deg,#ff7043,#ff9776)}
.tcard .who b{font-size:14px;font-weight:800}
.tcard .who span{font-size:12.5px;color:var(--muted)}
.tcard .st{font-size:13px;color:#f5a623;margin-left:auto}
.tcard p{font-size:14px;color:#4a5468;line-height:1.65;margin:0}

/* 신뢰 배지 행 */
.trust-row{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}
@media(max-width:680px){.trust-row{grid-template-columns:repeat(2,1fr)}}
.trust-row .tb{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px 12px;
  text-align:center}
.trust-row .tb .i{font-size:24px}
.trust-row .tb b{display:block;font-size:14px;font-weight:800;margin-top:8px}
.trust-row .tb span{display:block;font-size:12px;color:var(--muted);margin-top:3px}

/* 타임라인 */
.timeline{margin:22px 0;padding-left:8px}
.tl{position:relative;padding:0 0 22px 30px;border-left:2px solid var(--line)}
.tl:last-child{border-left:2px solid transparent;padding-bottom:0}
.tl::before{content:"";position:absolute;left:-7px;top:2px;width:12px;height:12px;border-radius:50%;
  background:var(--brand);box-shadow:0 0 0 4px var(--glow)}
.tl b{font-size:15px;font-weight:800}
.tl span{display:block;font-size:14px;color:var(--muted);margin-top:4px;line-height:1.6}

/* 정보 강조 카드 (아이콘+텍스트 가로) */
.infocard{display:flex;gap:16px;align-items:flex-start;background:#fff;border:1px solid var(--line);
  border-radius:16px;padding:20px 22px;margin:14px 0}
.infocard .ii{flex:0 0 46px;width:46px;height:46px;border-radius:13px;display:grid;place-items:center;
  font-size:22px;background:linear-gradient(135deg,#eef3ff,#f2effe)}
.infocard .tx b{font-size:15.5px;font-weight:800}
.infocard .tx p{font-size:14px;color:var(--muted);margin-top:5px;line-height:1.6}

/* 도넛 차트 행 */
.donuts{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}
@media(max-width:680px){.donuts{grid-template-columns:1fr}}
.donut{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;text-align:center}
.donut .ring{width:104px;height:104px;border-radius:50%;margin:0 auto 12px;display:grid;place-items:center;
  position:relative}
.donut .ring::before{content:"";position:absolute;inset:11px;border-radius:50%;background:#fff}
.donut .ring .v{position:relative;font-size:22px;font-weight:900;color:#2b3344}
.donut b{display:block;font-size:14px;font-weight:800}
.donut span{display:block;font-size:12.5px;color:var(--muted);margin-top:3px}

/* 선생님 프로필 샘플 */
.tutors{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}
@media(max-width:680px){.tutors{grid-template-columns:1fr}}
.tutor{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;text-align:center}
.tutor .ph{width:64px;height:64px;border-radius:50%;margin:0 auto 12px;display:grid;place-items:center;
  font-size:26px;color:#fff;background:linear-gradient(135deg,var(--brand),var(--brand2))}
.tutor .ph.t2{background:linear-gradient(135deg,#00b8d4,#00d4c8)}
.tutor .ph.t3{background:linear-gradient(135deg,#7c4dff,#b388ff)}
.tutor b{font-size:15px;font-weight:800}
.tutor .tag{font-size:12.5px;color:var(--brand);font-weight:700;margin-top:3px}
.tutor p{font-size:13px;color:var(--muted);margin-top:9px;line-height:1.55}
.tutor .stars{color:#f5a623;font-size:13px;margin-top:8px}

/* 시간표 그리드 */
.schedule{margin:22px 0;background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px 24px}
.schedule h3{font-size:16px;font-weight:800;margin-bottom:14px}
.sgrid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;font-size:12.5px}
.sgrid .d{text-align:center;font-weight:800;padding:8px 0;color:#384256}
.sgrid .c{text-align:center;padding:10px 0;border-radius:8px;background:#f0f4ff;color:var(--brand);font-weight:700}
.sgrid .c.off{background:#f4f5f8;color:#b8bfcc}

/* 인근 지역 링크 */
.nearby{margin:22px 0;background:linear-gradient(120deg,#f7f9fd,#f3effe);border:1px solid #e4eafd;
  border-radius:16px;padding:22px 24px}
.nearby h3{font-size:16px;font-weight:800;margin-bottom:12px}
.nearby .links{display:flex;gap:8px;flex-wrap:wrap}
.nearby .links a{font-size:13.5px;font-weight:700;padding:8px 14px;border-radius:999px;background:#fff;
  border:1px solid var(--line);color:#384256;transition:.16s}
.nearby .links a:hover{color:var(--brand);border-color:var(--brand)}

/* 중간 CTA 배너 */
.midcta{margin:24px 0;border-radius:20px;padding:30px;text-align:center;color:#fff;position:relative;
  overflow:hidden;background:linear-gradient(120deg,var(--brand),var(--brand2))}
.midcta::before{content:"";position:absolute;inset:0;opacity:.18;
  background-image:linear-gradient(rgba(255,255,255,.4) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.4) 1px,transparent 1px);
  background-size:28px 28px}
.midcta .ct{position:relative}
.midcta h3{font-size:22px;font-weight:900;letter-spacing:-.02em}
.midcta p{font-size:14.5px;opacity:.95;margin-top:8px}
.midcta button{margin-top:18px;background:#fff;color:var(--brand);font-weight:800;font-size:15px;
  padding:13px 28px;border:none;border-radius:12px;cursor:pointer;transition:.2s}
.midcta button:hover{transform:translateY(-2px)}

/* 보장 박스 */
.guarantee{display:flex;gap:14px;align-items:center;margin:22px 0;background:#fff;
  border:1.5px dashed var(--brand);border-radius:16px;padding:20px 24px}
.guarantee .g-ic{font-size:34px}
.guarantee b{font-size:16px;font-weight:800}
.guarantee p{font-size:14px;color:var(--muted);margin-top:4px}

/* 비용/혜택 카드 */
.benefit{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:22px 0}
@media(max-width:680px){.benefit{grid-template-columns:1fr}}
.bcard{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px 22px}
.bcard .h{display:flex;align-items:center;gap:9px;font-weight:800;font-size:15px}
.bcard .h .e{font-size:20px}
.bcard p{font-size:13.5px;color:var(--muted);margin-top:9px;line-height:1.6}

/* ═══════════════════════════════════════════════════════════ */
/* 메인 페이지 전용 사이버 다크 스타일                          */
/* ═══════════════════════════════════════════════════════════ */
.home{--hbg:#050818;--hink:#fff;--hmuted:#8390ab;--hbrand:#5a8dff;--hbrand2:#b347ff;--hacc:#00ffd0;--hneon:#ff2bd6;--hline:rgba(120,180,255,.12);
  background:var(--hbg);color:var(--hink);position:relative;overflow:hidden}
.home .h-bg{position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(40% 50% at 15% 20%,rgba(0,255,208,.18),transparent 60%),
    radial-gradient(50% 50% at 85% 30%,rgba(179,71,255,.20),transparent 60%),
    radial-gradient(40% 50% at 50% 100%,rgba(255,43,214,.10),transparent 60%),
    linear-gradient(180deg,#050818,#0a0a25 50%,#050818)}
.home .h-grid-floor{position:absolute;inset:0;pointer-events:none;perspective:600px;overflow:hidden;z-index:0}
.home .h-grid-floor::before{content:"";position:absolute;left:-20%;right:-20%;top:50%;bottom:-20%;
  background-image:linear-gradient(rgba(0,255,208,.20) 1px,transparent 1px),linear-gradient(90deg,rgba(0,255,208,.20) 1px,transparent 1px);
  background-size:60px 60px;transform:rotateX(60deg);
  mask-image:linear-gradient(180deg,transparent,#000 30%,#000 70%,transparent);
  animation:hfloor 12s linear infinite}
@keyframes hfloor{from{background-position:0 0}to{background-position:0 60px}}
.home .h-grid-top{position:absolute;inset:0;pointer-events:none;opacity:.4;z-index:0;
  background-image:linear-gradient(rgba(179,71,255,.10) 1px,transparent 1px),linear-gradient(90deg,rgba(90,141,255,.10) 1px,transparent 1px);
  background-size:50px 50px;mask-image:radial-gradient(70% 55% at 50% 30%,#000,transparent)}
.home .h-scan{position:absolute;inset:0;pointer-events:none;overflow:hidden;z-index:0}
.home .h-scan::before,.home .h-scan::after{content:"";position:absolute;left:0;right:0;height:1px;
  background:linear-gradient(90deg,transparent,var(--hacc),transparent);box-shadow:0 0 14px var(--hacc);
  animation:hscan 7s linear infinite}
.home .h-scan::after{background:linear-gradient(90deg,transparent,var(--hneon),transparent);
  box-shadow:0 0 14px var(--hneon);animation:hscan 9s linear infinite reverse;animation-delay:-2s}
@keyframes hscan{0%{top:-2%}100%{top:102%}}

/* 사이버 히어로 */
.home .h-hero{position:relative;z-index:2;padding:80px 24px;min-height:680px}
.home .h-wrap{max-width:1280px;margin:0 auto;display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
@media(max-width:880px){.home .h-wrap{grid-template-columns:1fr;gap:50px}}
.home .h-badge{display:inline-flex;align-items:center;gap:8px;background:rgba(0,255,208,.08);
  border:1px solid rgba(0,255,208,.45);padding:7px 14px;border-radius:99px;font-size:12.5px;font-weight:700;
  color:var(--hacc);letter-spacing:.05em;font-family:'JetBrains Mono',ui-monospace,monospace;
  box-shadow:0 0 20px rgba(0,255,208,.25)}
.home .h-badge::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--hacc);
  box-shadow:0 0 12px var(--hacc);animation:hp 1.5s infinite}
@keyframes hp{0%,100%{opacity:1}50%{opacity:.4}}
.home .h-h1{font-size:62px;font-weight:900;letter-spacing:-.04em;line-height:1.05;margin-top:20px;
  text-shadow:0 0 40px rgba(90,141,255,.3);color:#fff}
@media(max-width:880px){.home .h-h1{font-size:46px}}
.home .h-h1 .g{background:linear-gradient(100deg,var(--hacc),var(--hbrand),var(--hneon));
  -webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 0 24px rgba(179,71,255,.4))}
.home .h-sub{font-size:17px;color:var(--hmuted);margin-top:20px;max-width:480px;line-height:1.7}
.home .h-ctas{display:flex;gap:12px;margin-top:32px;flex-wrap:wrap}
.home .h-btn{font-size:14.5px;font-weight:800;padding:14px 26px;border-radius:12px;cursor:pointer;border:none;
  display:inline-flex;align-items:center;gap:8px;transition:.2s;font-family:inherit;color:#fff;text-decoration:none}
.home .h-btn-p{background:linear-gradient(100deg,var(--hbrand),var(--hbrand2));
  box-shadow:0 0 30px rgba(179,71,255,.4),0 12px 30px -10px var(--hbrand)}
.home .h-btn-p:hover{transform:translateY(-2px);box-shadow:0 0 40px rgba(179,71,255,.6)}
.home .h-btn-o{background:rgba(255,255,255,.04);border:1px solid var(--hline);backdrop-filter:blur(8px)}
.home .h-btn-o:hover{background:rgba(255,255,255,.08);border-color:var(--hacc)}
.home .h-stats{display:flex;gap:24px;margin-top:40px;padding-top:30px;border-top:1px solid var(--hline);flex-wrap:wrap}
.home .h-stats .s b{font-size:24px;font-weight:900;letter-spacing:-.02em;color:#fff;font-family:'JetBrains Mono',ui-monospace,monospace;
  text-shadow:0 0 14px rgba(0,255,208,.4)}
.home .h-stats .s span{display:block;font-size:12px;color:var(--hmuted);margin-top:3px;font-weight:600}

/* 우측 실사 + 떠다니는 카드 */
.home .h-visual{position:relative}
.home .h-img{position:relative;border-radius:18px;overflow:hidden;
  box-shadow:0 0 40px rgba(0,255,208,.15),0 0 80px rgba(179,71,255,.15),0 40px 80px -20px rgba(0,0,0,.7);
  transform:perspective(1400px) rotateY(-4deg) rotateX(2deg);transition:.4s;
  border:1px solid rgba(0,255,208,.25)}
.home .h-img:hover{transform:perspective(1400px) rotateY(-2deg) rotateX(1deg)}
.home .h-img img{width:100%;display:block;aspect-ratio:4/5;object-fit:cover;filter:saturate(.85) contrast(1.05)}
.home .h-img::after{content:"";position:absolute;inset:0;
  background:linear-gradient(180deg,transparent 30%,rgba(5,8,24,.7)),linear-gradient(120deg,rgba(0,255,208,.15),transparent 50%,rgba(179,71,255,.15))}
.home .h-fc{position:absolute;background:rgba(10,15,40,.85);backdrop-filter:blur(14px);
  border:1px solid rgba(0,255,208,.25);border-radius:14px;padding:14px 18px;
  box-shadow:0 0 25px rgba(0,255,208,.15),0 18px 40px -10px rgba(0,0,0,.6);z-index:3;color:#fff}
.home .h-fc-live{top:32px;left:-24px;display:flex;align-items:center;gap:10px;border-color:rgba(230,57,70,.5);box-shadow:0 0 25px rgba(230,57,70,.3)}
.home .h-fc-live .ld{width:9px;height:9px;border-radius:50%;background:#ff3b5c;box-shadow:0 0 14px #ff3b5c;animation:hp 1.2s infinite}
.home .h-fc-live b{font-size:12px;font-weight:900;letter-spacing:.08em}
.home .h-fc-live span{font-size:12px;color:var(--hmuted);margin-left:2px}
.home .h-fc-class{bottom:90px;left:-44px;min-width:240px}
.home .h-fc-class .top{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.home .h-fc-class .av{width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,var(--hbrand),var(--hbrand2));
  display:grid;place-items:center;font-size:14px;font-weight:900;color:#fff;box-shadow:0 0 16px rgba(179,71,255,.5)}
.home .h-fc-class .who b{font-size:13px;font-weight:800;display:block}
.home .h-fc-class .who span{font-size:11.5px;color:var(--hmuted)}
.home .h-fc-class .tmr{margin-left:auto;font-size:11px;color:var(--hacc);font-family:'JetBrains Mono',monospace;
  background:rgba(0,255,208,.1);padding:3px 8px;border-radius:5px;border:1px solid rgba(0,255,208,.3)}
.home .h-fc-class .meta{font-size:11.5px;color:var(--hmuted);display:flex;gap:14px;padding-top:8px;border-top:1px solid var(--hline)}
.home .h-fc-class .meta b{color:#fff;font-weight:700}
.home .h-fc-rate{top:50%;right:-30px;display:flex;align-items:center;gap:11px;border-color:rgba(255,43,214,.3);box-shadow:0 0 25px rgba(255,43,214,.2)}
.home .h-fc-rate .score{font-size:28px;font-weight:900;background:linear-gradient(100deg,var(--hacc),var(--hneon));
  -webkit-background-clip:text;background-clip:text;color:transparent;font-family:'JetBrains Mono',monospace}
.home .h-fc-rate .stars{font-size:14px;color:#febc2e;filter:drop-shadow(0 0 6px rgba(254,188,46,.5))}
.home .h-fc-rate .lbl{font-size:11px;color:var(--hmuted);margin-top:1px}
.home .h-fc-stats{bottom:-18px;right:30px;display:flex;align-items:center;gap:10px}
.home .h-fc-stats .ic{width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,var(--hbrand),var(--hbrand2));
  display:grid;place-items:center;font-size:15px;color:#fff;font-weight:900;font-family:monospace;box-shadow:0 0 16px rgba(90,141,255,.5)}
.home .h-fc-stats b{font-size:14px;font-weight:900;display:block}
.home .h-fc-stats span{font-size:11.5px;color:var(--hmuted)}
@media(max-width:880px){.home .h-fc{display:none}}

/* 사이버 섹션 공통 */
.home .h-section{position:relative;z-index:2;padding:80px 24px}
.home .h-section .h-wrap2{max-width:1160px;margin:0 auto}
.home .h-head{text-align:center;margin-bottom:46px}
.home .h-head .k{font-size:13px;font-weight:800;color:var(--hacc);letter-spacing:.15em;font-family:'JetBrains Mono',monospace;
  display:inline-flex;align-items:center;gap:8px;padding:6px 14px;border:1px solid rgba(0,255,208,.3);border-radius:99px;
  background:rgba(0,255,208,.05);box-shadow:0 0 20px rgba(0,255,208,.15)}
.home .h-head .k::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--hacc);box-shadow:0 0 10px var(--hacc)}
.home .h-head h2{font-size:42px;font-weight:900;letter-spacing:-.03em;margin-top:16px;color:#fff;text-shadow:0 0 30px rgba(90,141,255,.3)}
.home .h-head h2 .g{background:linear-gradient(100deg,var(--hacc),var(--hbrand),var(--hneon));-webkit-background-clip:text;background-clip:text;color:transparent}
.home .h-head p{color:var(--hmuted);margin-top:10px;font-size:13px;font-family:'JetBrains Mono',monospace;letter-spacing:.05em}
.home .h-head p::before{content:"// "}

/* 과목 섹션 (인터랙티브) */
.home .h-subj{display:grid;grid-template-columns:1.1fr 1fr;gap:18px}
@media(max-width:780px){.home .h-subj{grid-template-columns:1fr}}
.home .h-feat{background:linear-gradient(135deg,#0b1020,#1a2238);color:#fff;border:1px solid var(--hline);
  border-radius:24px;padding:36px;display:flex;flex-direction:column;justify-content:space-between;
  min-height:340px;cursor:pointer;transition:.2s;position:relative;overflow:hidden;
  box-shadow:0 0 40px rgba(0,255,208,.1)}
.home .h-feat:hover{transform:translateY(-4px);box-shadow:0 0 60px rgba(0,255,208,.2)}
.home .h-feat .bg-text{position:absolute;right:-40px;bottom:-70px;font-size:280px;font-weight:900;
  color:rgba(255,255,255,.04);line-height:1;transition:.4s;pointer-events:none}
.home .h-feat::after{content:"";position:absolute;inset:0;opacity:.08;pointer-events:none;
  background-image:linear-gradient(rgba(0,255,208,.5) 1px,transparent 1px),linear-gradient(90deg,rgba(0,255,208,.5) 1px,transparent 1px);
  background-size:32px 32px}
.home .h-feat>*{position:relative;z-index:1}
.home .h-feat .top{display:flex;align-items:center;gap:10px}
.home .h-feat .live{font-size:11px;font-weight:900;color:#fff;background:#e63946;padding:4px 10px;border-radius:5px;letter-spacing:.05em;display:inline-flex;align-items:center;gap:5px}
.home .h-feat .live::before{content:"";width:6px;height:6px;border-radius:50%;background:#fff;animation:hp 1.2s infinite}
.home .h-feat .tag{font-size:12px;font-weight:800;color:var(--hacc);letter-spacing:.12em;font-family:'JetBrains Mono',monospace}
.home .h-feat h3{font-size:54px;font-weight:900;letter-spacing:-.04em;margin-top:18px;line-height:1;transition:.3s}
.home .h-feat .sub{font-size:15px;color:rgba(255,255,255,.75);margin-top:12px;max-width:340px;line-height:1.6}
.home .h-feat .meta{display:flex;gap:18px;margin-top:22px;flex-wrap:wrap}
.home .h-feat .meta div{font-size:13px;color:rgba(255,255,255,.7)}
.home .h-feat .meta b{font-size:16px;font-weight:900;color:#fff;display:block;font-family:'JetBrains Mono',monospace}
.home .h-feat .go{font-size:14px;font-weight:800;display:inline-flex;align-items:center;gap:8px;
  background:#fff;color:#0b1020;padding:12px 20px;border-radius:10px;width:fit-content;margin-top:22px;text-decoration:none}
.home .h-fade{animation:hfade .35s ease}
@keyframes hfade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.home .h-list{background:rgba(10,15,40,.6);backdrop-filter:blur(10px);border:1px solid var(--hline);border-radius:24px;padding:14px 24px;
  display:flex;flex-direction:column;justify-content:center}
.home .h-item{display:flex;align-items:center;gap:18px;padding:20px 0;border-bottom:1px dashed var(--hline);cursor:pointer;
  position:relative;transition:.18s;color:#fff}
.home .h-item:last-child{border-bottom:0}
.home .h-item .dot{width:10px;height:10px;border-radius:50%;background:var(--hline);transition:.3s;flex:0 0 10px}
.home .h-item:hover,.home .h-item.act{padding-left:8px}
.home .h-item:hover .dot,.home .h-item.act .dot{background:var(--hacc);box-shadow:0 0 0 6px rgba(0,255,208,.15);transform:scale(1.3)}
.home .h-item:hover .nm,.home .h-item.act .nm{color:var(--hacc)}
.home .h-item .nm{font-size:22px;font-weight:800;letter-spacing:-.02em;flex:1;transition:.2s}
.home .h-item .nm small{font-size:13px;font-weight:600;color:var(--hmuted);margin-left:10px}
.home .h-item .live{font-size:10px;font-weight:900;color:#fff;background:#e63946;padding:3px 8px;border-radius:5px}
.home .h-item .arr{font-size:18px;opacity:.3;transition:.2s}
.home .h-item:hover .arr,.home .h-item.act .arr{opacity:1;transform:translateX(4px)}

/* WHY 카드 (사이버) */
.home .h-why{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
@media(max-width:880px){.home .h-why{grid-template-columns:1fr}}
.home .h-card{position:relative;background:rgba(10,15,40,.6);backdrop-filter:blur(10px);
  border:1px solid var(--hline);border-radius:18px;padding:34px 28px;overflow:hidden;transition:.3s}
.home .h-card:hover{transform:translateY(-6px);background:rgba(10,15,40,.85);box-shadow:0 0 40px rgba(0,255,208,.15)}
.home .h-card .cn{position:absolute;width:24px;height:24px;opacity:.6}
.home .h-card .cn.tl{top:10px;left:10px;border-top:1px solid var(--hacc);border-left:1px solid var(--hacc)}
.home .h-card .cn.tr{top:10px;right:10px;border-top:1px solid var(--hneon);border-right:1px solid var(--hneon)}
.home .h-card .cn.bl{bottom:10px;left:10px;border-bottom:1px solid var(--hneon);border-left:1px solid var(--hneon)}
.home .h-card .cn.br{bottom:10px;right:10px;border-bottom:1px solid var(--hacc);border-right:1px solid var(--hacc)}
.home .h-card .no{font-size:11px;font-weight:700;color:var(--hmuted);font-family:'JetBrains Mono',monospace;letter-spacing:.1em;margin-bottom:18px}
.home .h-card .no b{color:var(--hacc);text-shadow:0 0 8px var(--hacc)}
.home .h-card .iconbox{width:64px;height:64px;border-radius:14px;
  background:linear-gradient(135deg,rgba(0,255,208,.1),rgba(179,71,255,.1));
  border:1px solid rgba(0,255,208,.3);display:grid;place-items:center;margin-bottom:20px;
  box-shadow:inset 0 0 20px rgba(0,255,208,.1),0 0 20px rgba(0,255,208,.15)}
.home .h-card .iconbox svg{width:32px;height:32px}
.home .h-card:nth-child(2) .iconbox{border-color:rgba(179,71,255,.3);box-shadow:inset 0 0 20px rgba(179,71,255,.1),0 0 20px rgba(179,71,255,.15)}
.home .h-card:nth-child(3) .iconbox{border-color:rgba(255,43,214,.3);box-shadow:inset 0 0 20px rgba(255,43,214,.1),0 0 20px rgba(255,43,214,.15)}
.home .h-card h3{font-size:22px;font-weight:900;color:#fff;margin-bottom:10px}
.home .h-card p{font-size:14.5px;color:var(--hmuted);line-height:1.7}
.home .h-card .data{display:flex;align-items:center;gap:8px;margin-top:18px;padding-top:16px;
  border-top:1px dashed var(--hline);font-family:'JetBrains Mono',monospace;font-size:11.5px;color:var(--hacc)}
.home .h-card .data b{color:#fff}
.home .h-card .data .ld{width:6px;height:6px;border-radius:50%;background:var(--hacc);box-shadow:0 0 8px var(--hacc);animation:hp 1.5s infinite}
.home .h-card:nth-child(2) .data{color:var(--hbrand2)}
.home .h-card:nth-child(2) .data .ld{background:var(--hbrand2);box-shadow:0 0 8px var(--hbrand2)}
.home .h-card:nth-child(3) .data{color:var(--hneon)}
.home .h-card:nth-child(3) .data .ld{background:var(--hneon);box-shadow:0 0 8px var(--hneon)}

/* 지역 섹션 (다크) */
.home .h-rtabs{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-bottom:26px}
.home .h-rt{font-size:14px;font-weight:700;padding:9px 16px;border-radius:99px;background:rgba(10,15,40,.6);
  border:1px solid var(--hline);color:#fff;cursor:pointer;transition:.18s;font-family:inherit}
.home .h-rt:hover,.home .h-rt.on{background:var(--hbrand);color:#fff;border-color:var(--hbrand);box-shadow:0 0 14px rgba(90,141,255,.5)}
.home .h-rlist{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px}
.home .h-rlist a{font-size:14px;padding:11px 14px;border-radius:12px;background:rgba(10,15,40,.6);backdrop-filter:blur(6px);
  border:1px solid var(--hline);color:var(--hmuted);font-weight:600;transition:.16s;text-decoration:none;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.home .h-rlist a:hover{color:var(--hacc);border-color:var(--hacc);background:rgba(0,255,208,.08)}

/* 메인일 때 헤더 다크 처리 */
body.dark-home{background:#050818}
body.dark-home header.nav{background:rgba(7,11,28,.92);border-bottom:1px solid rgba(0,255,208,.16);box-shadow:0 1px 24px rgba(0,0,0,.45);backdrop-filter:blur(14px)}
body.dark-home header.nav .logo{color:#fff}
body.dark-home header.nav .logo .on{color:#ff5577}
body.dark-home header.nav .nav-cta{background:linear-gradient(135deg,#00ffd0,#00b8d4);color:#04121a;box-shadow:0 0 18px rgba(0,255,208,.35)}
/* 다크 홈 푸터 */
body.dark-home footer{background:#070b1c;border-top:1px solid rgba(0,255,208,.15)}
body.dark-home footer .logo{color:#fff}
body.dark-home footer .foot-top p{color:#8390ab!important}
body.dark-home footer .foot-links a{color:#8390ab}
body.dark-home footer .foot-links a:hover{color:#00ffd0}
body.dark-home footer .foot-bot{color:#8390ab;border-top-color:rgba(120,180,255,.12)}
body.dark-home footer .notice{color:#6b7693}

/* 레이더 지도 (지역 섹션) */
.home .h-radar{display:grid;grid-template-columns:440px 1fr;gap:20px;background:linear-gradient(180deg,rgba(12,18,42,.7),rgba(7,11,28,.6));
  border:1px solid var(--hline);border-radius:22px;padding:24px;box-shadow:inset 0 1px 0 rgba(255,255,255,.05),0 24px 60px -20px rgba(0,0,0,.8),0 0 50px rgba(0,255,208,.1)}
@media(max-width:860px){.home .h-radar{grid-template-columns:1fr}}
@media(max-width:600px){
  .home .h-hero{padding:52px 18px;min-height:auto}
  .home .h-section{padding:52px 18px}
  .home .h-h1{font-size:34px}
  .home .h-sub{font-size:15.5px}
  .home .h-head h2{font-size:27px}
  .home .h-stats{flex-wrap:nowrap;gap:10px;justify-content:space-between}
  .home .h-stats .s b{font-size:18px}
  .home .h-stats .s span{font-size:10.5px}
  .home .h-feat{min-height:auto}
  .home .h-visual{margin-top:22px}
  .home .h-fc{display:flex;position:static;inset:auto;transform:none;min-width:0;width:100%;margin:10px 0 0;box-sizing:border-box}
  .home .h-fc-class{min-width:0}
  .home .h-feat h3{font-size:40px}
  .home .h-feat .bg-text{font-size:180px;bottom:-46px;right:-24px}
  .home .h-radar{padding:16px}
  .home .rdongs{grid-template-columns:repeat(auto-fill,minmax(104px,1fr));max-height:360px}
}
.home .rmap-box{display:flex;flex-direction:column;gap:14px}
.home .rmap{position:relative;width:100%;border-radius:16px;overflow:hidden;
  background:radial-gradient(circle at 50% 45%,rgba(0,255,208,.05),transparent 70%);
  border:1px solid rgba(0,255,208,.15);aspect-ratio:891/813;box-shadow:inset 0 0 40px rgba(0,0,0,.6),inset 0 2px 0 rgba(255,255,255,.04)}
.home .rmap>svg{position:absolute;inset:0;width:100%;height:100%}
.home .kr-prov{fill:rgba(55,105,205,.22);stroke:#00ffd0;stroke-width:.8;stroke-linejoin:round;cursor:pointer;transform-box:fill-box;transform-origin:center;transition:transform .18s ease,fill .18s,filter .18s;filter:drop-shadow(0 5px 6px rgba(0,0,0,.75)) drop-shadow(0 -1px 1px rgba(130,225,255,.3))}
.home .kr-prov.on{fill:rgba(0,255,208,.32);stroke:#3df0e0;filter:drop-shadow(0 0 9px rgba(0,255,208,.95));transform:scale(1.13)}
.home .rgrid line{stroke:rgba(0,255,208,.10);stroke-width:.5}
.home .rring{fill:none;stroke:rgba(0,255,208,.12);stroke-width:.6}
.home .sweep{transform-origin:500.0px 434.2px;animation:rsweep 4s linear infinite}
@keyframes rsweep{to{transform:rotate(360deg)}}
.home .sweep,.home .rgrid,.home .rring{pointer-events:none}
.home .prov-node{cursor:pointer}
.home .prov-node circle{fill:var(--hacc);filter:drop-shadow(0 0 4px var(--hacc));transition:r .18s}
.home .prov-node text{fill:#dffff6;font-size:13px;font-weight:700;text-anchor:middle;dominant-baseline:middle;pointer-events:none;paint-order:stroke;stroke:#05071a;stroke-width:3.5px;stroke-linejoin:round;font-family:'Pretendard',sans-serif;transition:font-size .18s,fill .18s}
.home .prov-node.on circle{fill:#3df0e0;r:5;filter:drop-shadow(0 0 9px #3df0e0)}
.home .prov-node.on text{font-size:26px;fill:#fff;stroke-width:5px}
.home .jbox{fill:rgba(8,16,40,.6);stroke:rgba(0,255,208,.4);stroke-width:1;stroke-dasharray:4 3}
.home .jlabel{fill:#7fffe0;font-size:11px;font-weight:700;font-family:'Pretendard',sans-serif;transition:font-size .18s}
.home .jlabel.on{font-size:15px;fill:#fff}
.home .rmap-stat{display:flex;justify-content:space-between;font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--hmuted)}
.home .rmap-stat b{color:var(--hacc)}
.home .rpanel{display:flex;flex-direction:column}
.home .rsearch{position:relative;margin-bottom:16px}
.home .rsearch input{width:100%;background:rgba(0,0,0,.3);border:1px solid var(--hline);border-radius:12px;
  padding:14px 16px 14px 44px;color:#fff;font-size:14px;font-family:inherit;outline:none;transition:.2s}
.home .rsearch input:focus{border-color:var(--hacc);box-shadow:0 0 0 3px rgba(0,255,208,.12)}
.home .rsearch input::placeholder{color:var(--hmuted)}
.home .rsearch .si{position:absolute;left:15px;top:50%;transform:translateY(-50%);color:var(--hacc)}
.home .rph{font-family:'JetBrains Mono',monospace;font-size:12px;color:var(--hmuted);margin-bottom:14px;display:flex;align-items:center;gap:8px}
.home .rph .live{width:7px;height:7px;border-radius:50%;background:var(--hneon);box-shadow:0 0 8px var(--hneon);animation:rnp 1.2s infinite}
.home .rph b{color:#fff}
.home .rdongs{display:grid;grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:8px;max-height:440px;overflow-y:auto;padding-right:4px}
.home .rdongs a{font-size:13px;padding:11px 12px;border-radius:11px;background:linear-gradient(180deg,rgba(120,160,255,.24),rgba(40,70,160,.05));border:1px solid var(--hline);border-top-color:rgba(255,255,255,.18);
  color:var(--hmuted);font-weight:600;text-decoration:none;transition:transform .15s,box-shadow .15s,background .15s,color .15s,border-color .15s;display:flex;align-items:center;justify-content:space-between;gap:5px;
  white-space:nowrap;overflow:hidden;box-shadow:inset 0 1px 0 rgba(255,255,255,.18),inset 0 -3px 6px rgba(0,0,0,.45),0 7px 16px rgba(0,0,0,.55)}
.home .rdongs a span.dn{overflow:hidden;text-overflow:ellipsis}
.home .rdongs a .ar{color:var(--hacc);opacity:0;transition:.15s;flex:0 0 auto}
.home .rdongs a:hover{color:#fff;border-color:var(--hacc);background:linear-gradient(180deg,rgba(0,255,208,.24),rgba(0,150,130,.06));transform:translateY(-3px);box-shadow:inset 0 1px 0 rgba(255,255,255,.25),inset 0 -3px 6px rgba(0,0,0,.4),0 12px 24px rgba(0,255,208,.28)}
.home .rdongs a:hover .ar{opacity:1}
.home .rdongs::-webkit-scrollbar{width:6px}
.home .rdongs::-webkit-scrollbar-thumb{background:rgba(0,255,208,.2);border-radius:3px}
`;

